import type { OsmFeature } from "osm-api";

export interface Coordinates {
  lat: number;
  lon: number;
}

export interface OverpassRequest {
  version: number;
  generator: string;
  osm3s: {
    timestamp_osm_base: string;
    timestamp_areas_base: string;
    copyright: string;
  };
  elements: OsmFeature[];
}

/** Regions generated by reverse-geocoding-data are of this type*/
export interface GeographicFolderElement {
  type: "geographic";
  name: string;
  /** Bounding box of the region, in degrees */
  bbox?: { x0: number; x1: number; y0: number; y1: number };
}

export type DataJSON = OsmFeature | GeographicFolderElement;
